require __DIR__ . '/_bootstrap.php';$id=(int)($_GET['id']??0);$result=$clinicalNoteService->getNoteVersions($id,$currentUser);if(!($result['success']??false)){http_response_code(!empty($result['audit_failed'])?503:403);exit('Clinical Note history is unavailable.');}$note=$result['data']['note'];$versions=$result['data']['versions'];$amendments=$result['data']['amendments'];$canApprove=$permissionService->canApproveNoteAmendments((int)$note['patient_id'],$currentUser);$pageTitle='Clinical Note History';$moduleStylesheet='/modules/medical_records/assets/medical_records.css';require __DIR__.'/../../../layouts/header.php';require __DIR__.'/../../../layouts/sidebar.php';
?><div class="main-container"><?php require __DIR__.'/../../../layouts/navbar.php';?><main class="content"><h1>Clinical Note Version History</h1><p>Note #<?=(int)$note['id']?>. Versions and amendment decisions are immutable clinical history.</p><?php foreach($versions as $version):?><section class="card"><div class="card-header"><h2>Version <?=(int)$version['version_number']?> — <?=e($version['version_status'])?></h2><span><?=e($version['created_at'])?></span></div><p><strong>Author:</strong> <?=e($version['author_name'])?> · <strong>Confidentiality:</strong> <?=e($version['confidentiality_level'])?></p><?php if($version['masked']):?><div class="alert-info">This version is protected by its stored confidentiality classification.</div><?php else:?><div style="white-space:pre-wrap"><?=e($version['content'])?></div><?php if($version['amendment_reason']):?><p><strong>Reason:</strong> <?=e($version['amendment_reason'])?></p><?php endif;?><?php endif;?></section><?php endforeach;?>
<section class="card"><h2>Amendment Requests</h2><?php if(!$amendments):?><div class="empty-state">No amendment requests.</div><?php else:?><table class="summary-table"><thead><tr><th>ID</th><th>Status</th><th>Requester</th><th>Reason</th><th>Date</th><th>Review</th></tr></thead><tbody><?php foreach($amendments as $amendment):?><tr><td>#<?=(int)$amendment['id']?></td><td><?=e($amendment['status'])?></td><td><?=e($amendment['requested_by_name'])?></td><td><?=e($amendment['reason'])?><?php if(!empty($amendment['proposed_changes']['review_reason'])):?><br><strong>Review reason:</strong> <?=e($amendment['proposed_changes']['review_reason'])?><?php endif;?></td><td><?=e($amendment['requested_at'])?></td><td><?php if($canApprove&&$amendment['status']==='Requested'):?><form class="inline-form" method="post" action="amendment_review.php"><?=csrfField()?><input type="hidden" name="amendment_id" value="<?=(int)$amendment['id']?>"><input type="hidden" name="note_id" value="<?=(int)$note['id']?>"><button name="decision" value="approve" class="btn-primary">Approve</button><input name="reason" placeholder="Reason required to reject"><button name="decision" value="reject" class="btn-secondary">Reject</button></form><?php else:?><?=e($amendment['reviewed_by_name']??'Pending')?><?php endif;?></td></tr><?php endforeach;?></tbody></table><?php endif;?></section><a href="view.php?id=<?=(int)$note['id']?>">Back to Note</a></main><?php require __DIR__.'/../../../layouts/footer.php';?></div>
